import importlib
for mod in ['pandas', 'openpyxl', 'xlrd', 'odf', 'xlsxwriter']:
    try:
        m = importlib.import_module(mod)
        print(mod, "OK", getattr(m, '__version__', ''))
    except Exception as e:
        print(mod, "MISSING", e)

